BEGIN;
DO $qa$
DECLARE b uuid:=gen_random_uuid();c uuid:=gen_random_uuid();m uuid:=gen_random_uuid();d1 uuid:=gen_random_uuid();d2 uuid:=gen_random_uuid();o1 uuid:=gen_random_uuid();o2 uuid:=gen_random_uuid();a2 uuid:=gen_random_uuid();ch uuid:=gen_random_uuid();desk1 text:='qa-'||gen_random_uuid();desk2 text:='qa-'||gen_random_uuid();v jsonb;checks int:=0;
BEGIN
 INSERT INTO public.ff_branches(id,code,name) VALUES(b,'qa-stage-'||b,'QA branch');
 INSERT INTO auth.users(id) VALUES(c),(m);
 INSERT INTO public.ff_profiles(user_id,display_name,role,active) VALUES(c,'QA STEP12 cashier','cashier',true),(m,'QA STEP12 manager','manager',true);
 INSERT INTO public.ff_user_branches(user_id,branch_id) VALUES(c,b);
 INSERT INTO public.ff_drivers(id,name,branch_id) VALUES(d1,'QA driver1',b),(d2,'QA driver2',b);
 INSERT INTO public.ff38_driver_presence(driver_id,state,checked_in_at,last_seen_at) VALUES(d1,'busy',now(),now()),(d2,'busy',now(),now()) ON CONFLICT(driver_id) DO UPDATE SET state=excluded.state,checked_in_at=excluded.checked_in_at,last_seen_at=excluded.last_seen_at;
 INSERT INTO public.ff_orders(id,order_number,branch_id,phone_snapshot,business_date,driver_id,status) VALUES(o1,-(1+floor(random()*1e12)::bigint),b,'000000000',public.ff_business_date(now()),d1,'sent'),(o2,-(1+floor(random()*1e12)::bigint),b,'000000000',public.ff_business_date(now()),d2,'sent');
 INSERT INTO public.ff38_delivery_tasks(order_id,driver_id) VALUES(o1,d1),(o2,d2);
 INSERT INTO public.ff_luxe_cashier_desks(code,label,branch_id,sort_order) VALUES(desk1,'QA desk 1',b,1),(desk2,'QA desk 2',b,2);
 INSERT INTO public.ff_luxe_cashier_staff_desks(user_id,desk_code,assigned_by) VALUES(c,desk1,m);
 INSERT INTO public.ff_luxe_cashier_order_desks(order_id,desk_code) VALUES(o1,desk1),(o2,desk2);
 PERFORM set_config('request.jwt.claim.sub',m::text,true);
 INSERT INTO public.ff_order_items(order_id,item_name,quantity,unit_price,line_total,item_notes) VALUES(o1,'QA own item',1,100,100,'QA own note'),(o2,'QA foreign item',1,100,100,'QA foreign note');
 INSERT INTO public.ff38_order_additions(id,order_id,requested_by) VALUES(a2,o2,m);
 INSERT INTO public.ff50_order_changes(id,order_id,old_items,new_items,old_total,new_total,reason,requested_by) VALUES(ch,o2,'[]','[]',0,0,'QA change',m);
 PERFORM set_config('request.jwt.claim.sub',c::text,true);SET LOCAL ROLE authenticated;
 BEGIN PERFORM public.ff49_cashier_receive(o2);RAISE EXCEPTION 'Foreign receive accepted' USING ERRCODE='ZQA12';EXCEPTION WHEN SQLSTATE '42501' THEN NULL;END;checks:=checks+1;
 BEGIN PERFORM public.ff49_cashier_invoice(o2,'QA');RAISE EXCEPTION 'Foreign invoice accepted' USING ERRCODE='ZQA12';EXCEPTION WHEN SQLSTATE '42501' THEN NULL;END;checks:=checks+1;
 BEGIN PERFORM public.ff38_cashier_set_stage(o2,'printed');RAISE EXCEPTION 'Foreign stage accepted' USING ERRCODE='ZQA12';EXCEPTION WHEN SQLSTATE '42501' THEN NULL;END;checks:=checks+1;
 BEGIN PERFORM public.ff50_change_cashier_decide(ch,true,'QA');RAISE EXCEPTION 'Foreign change accepted' USING ERRCODE='ZQA12';EXCEPTION WHEN SQLSTATE '42501' THEN NULL;END;checks:=checks+1;
 BEGIN PERFORM public.ff38_cashier_invoice_addition(a2);RAISE EXCEPTION 'Foreign addition accepted' USING ERRCODE='ZQA12';EXCEPTION WHEN SQLSTATE '42501' THEN NULL;END;checks:=checks+1;
 IF NOT EXISTS(SELECT FROM public.ff70_visible_item_notes() n WHERE n.order_id=o1) OR EXISTS(SELECT FROM public.ff70_visible_item_notes() n WHERE n.order_id=o2) THEN RAISE EXCEPTION 'Item notes isolation failed';END IF;checks:=checks+1;
 v:=public.ff49_cashier_receive(o1);IF v->>'received'<>'true' THEN RAISE EXCEPTION 'Own receipt failed';END IF;checks:=checks+1;
 v:=public.ff49_cashier_invoice(o1,'QA own invoice');IF v->>'stage'<>'printed' THEN RAISE EXCEPTION 'Own invoice failed';END IF;checks:=checks+1;
 v:=public.ff38_cashier_set_stage(o1,'preparing');IF v->>'stage'<>'preparing' THEN RAISE EXCEPTION 'Own stage failed';END IF;checks:=checks+1;
 RESET ROLE;
 IF EXISTS(SELECT FROM public.ff49_cashier_receipts WHERE order_id=o2) OR (SELECT cashier_stage FROM public.ff38_delivery_tasks WHERE order_id=o2)<>'waiting' THEN RAISE EXCEPTION 'Unauthorized state mutation';END IF;checks:=checks+1;
 UPDATE public.ff50_order_changes SET status='service_confirmed' WHERE id=ch;
 SET LOCAL ROLE authenticated;PERFORM set_config('request.jwt.claim.sub',c::text,true);
 BEGIN PERFORM public.ff50_change_cashier_confirm_pos(ch,'QA');RAISE EXCEPTION 'Foreign POS change accepted' USING ERRCODE='ZQA12';EXCEPTION WHEN SQLSTATE '42501' THEN NULL;END;checks:=checks+1;
 PERFORM set_config('request.jwt.claim.sub',m::text,true);
 IF NOT EXISTS(SELECT FROM public.ff70_visible_item_notes() n WHERE n.order_id=o2) THEN RAISE EXCEPTION 'Manager note scope failed';END IF;checks:=checks+1;
 RESET ROLE;
 IF checks<>12 THEN RAISE EXCEPTION 'Incomplete cashier lifecycle scope';END IF;
END $qa$;
SELECT 'PASS STEP12 cashier lifecycle desk scope: 12 assertions' result;
ROLLBACK;
